#define debugArr(...) std::cerr << __LINE__ << ": [", __DEBUG_UTIL__::printerArr(#__VA_ARGS__, __VA_ARGS__)
#else
#define debug(...)
#define debugArr(...)
#endif
const int maxn = 200005;
vector<pair<int, long long>> adj[maxn];
long long dist[maxn][2][2];
struct stor {
    long long dist;
    int u;
    int skip;
    int dbl;
    bool operator>(const stor& other) const {
        return dist > other.dist;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int n, m;
    cin >> n >> m;
    for (int i = 1; i <= m; i++) {
        int u, v;
        long long w;
        cin >> u >> v >> w;
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }
    priority_queue<stor, vector<stor>, greater<stor>> pq;
    for (int i = 1; i <= n; i++) {
        for (int j = 0; j < 2; j++) {
            for (int k = 0; k < 2; k++) {
                dist[i][j][k] = LLONG_MAX;
            }
        }
    }
    dist[1][0][0] = 0;
    pq.push({0, 1, 0, 0});

    while (!pq.empty()) {
        stor curr = pq.top();
        pq.pop();

        if (curr.dist > dist[curr.u][curr.skip][curr.dbl]) continue;

        for (const auto& edge : adj[curr.u]) {
            int v = edge.first;
            long long w = edge.second;
            if (dist[v][curr.skip][curr.dbl] > curr.dist + w) {
                dist[v][curr.skip][curr.dbl] = curr.dist + w;
                pq.push({dist[v][curr.skip][curr.dbl], v, curr.skip, curr.dbl});
            }
            if (curr.skip == 0) {
                if (dist[v][1][curr.dbl] > curr.dist) {
                    dist[v][1][curr.dbl] = curr.dist;
                    pq.push({dist[v][1][curr.dbl], v, 1, curr.dbl});
                }
            }
            if (curr.dbl == 0) {
                if (dist[v][curr.skip][1] > curr.dist + 2 * w) {
                    dist[v][curr.skip][1] = curr.dist + 2 * w;
                    pq.push({dist[v][curr.skip][1], v, curr.skip, 1});
                }
            }
            if (curr.skip == 0 && curr.dbl == 0) {
                if (dist[v][1][1] > curr.dist + w) {
                    dist[v][1][1] = curr.dist + w;
                    pq.push({dist[v][1][1], v, 1, 1});
                }
            }
        }
    }
    for (int i = 2; i <= n; i++) {
        cout << dist[i][1][1] << ' ';
    }
}